// --- 1. Obtener datos de entrada ---
// El array de fases requeridas desde el nodo de configuración.
const fasesRequeridas = $('Configuración de Fases').first().json.fases_requeridas;
// El array de campañas activas que vienen del nodo Aggregate.
const campañasActivas = $('Aggregate').first().json.campañas;

// --- 2. Variables de estado ---
let ready = false; // Valor por defecto
let todasLasFasesPresentes = true; // Asumimos que están todas hasta que se demuestre lo contrario

// Si no hay campañas activas o no se definieron fases, no puede estar listo.
if (!campañasActivas || campañasActivas.length === 0 || !fasesRequeridas || fasesRequeridas.length === 0) {
  todasLasFasesPresentes = false;
}

// --- 3. Lógica de Verificación de Fases ---
if (todasLasFasesPresentes) {
  const nombresDeCampañas = campañasActivas.map(c => c.name.toUpperCase());

  for (const fase of fasesRequeridas) {
    const regex = new RegExp(fase.regex, 'i'); // 'i' para que no distinga mayúsculas/minúsculas

    // Busca si al menos UNA campaña activa coincide con la regex de la fase.
    const faseEncontrada = nombresDeCampañas.some(nombre => regex.test(nombre));

    // Si no se encontró, marcamos como falso y rompemos el bucle.
    if (!faseEncontrada) {
      todasLasFasesPresentes = false;
      break;
    }
  }
}

// --- 4. Lógica de Verificación de Fecha (Solo si todas las fases están presentes) ---
// Este bloque solo se ejecuta si la validación anterior fue exitosa.
if (todasLasFasesPresentes) {

  // 1. Encontrar la fecha de creación más reciente
  const todosLosTimestamps = campañasActivas.map(c => new Date(c.created_time).getTime());
  const timestampMasReciente = Math.max(...todosLosTimestamps);
  const fechaMasReciente = new Date(timestampMasReciente);
  fechaMasReciente.setHours(0, 0, 0, 0); // <-- LÍNEA MODIFICADA (Ignoramos la hora)

  // 2. Calcular la fecha de "hace 7 días"
  const hoy = new Date();
  const hace7Dias = new Date();
  hace7Dias.setDate(hoy.getDate() - 7);
  hace7Dias.setHours(0, 0, 0, 0); // <-- LÍNEA MODIFICADA (Ignoramos la hora)

  // 3. Comparar.
  // "ready" es true solo si han pasado MÁS de 7 días,
  // es decir, la fecha más reciente es ANTERIOR a "hace 7 días".
  if (fechaMasReciente < hace7Dias) {
    ready = true;
  }
  // Si la fecha más reciente es igual o posterior a "hace 7 días", 'ready' se queda en 'false'.
}

// --- 5. Salida ---
// Siempre retorna un item con el estado de 'ready'.
return [{
  json: {
    ready: ready
  }
}];

// --- 1. Acceso a los datos de entrada ---

// Datos del cliente
const clientData = $('data-entry').first().json;
// Datos de la verificación (del nodo anterior)
const analisisFases = $input.first().json;

// --- 2. Filtro de Seguridad ---
// Este nodo solo debe construir el mensaje si 'ready' es true.
if (!analisisFases.ready) {
  return []; 
}

// --- 3. Extracción de Datos ---
const { nombre: clienteNombre, "ID-cuenta-publicitaria": idCuentaPublicitaria } = clientData;

// --- 4. Construcción del Texto de Análisis ---
const estadoGeneral = "Acción Requerida";
const tituloAnalisis = "✅ Listo para Fase 5";

// Se prepara la información del cliente.
const infoCliente = `*Cliente:* ${clienteNombre}\n*ID Cuenta:* ${idCuentaPublicitaria}`;

// Se prepara el contexto (simplificado).
const motivoAlerta = `\n*Motivo:* Han pasado +7 días con todas las fases activas.`;

// Se ensambla el texto final.
const textoFinal = `${tituloAnalisis}\n\n${infoCliente}\n${motivoAlerta}`;

// --- 5. Objeto de Salida ---
return [{
    json: {
        estado_general: estadoGeneral,
        texto_final: textoFinal
    }
}];

